namespace App\Jobs;

use App\Models\BankAccount;
use App\Models\User;
use App\Mail\StatementExportMailable;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Support\Facades\Mail;
use RuntimeException;

class ExportAccountStatementJob implements ShouldQueue
{
    use Dispatchable, Queueable;

    public function __construct(public int $userId, public int $accountId)
    {
    }

    public function handle(): void
    {
        $user = User::findOrFail($this->userId);
        $account = $user->bankAccounts()->with('transactions')->findOrFail($this->accountId);

        Mail::to($user->email)->send(new StatementExportMailable($account));
    }
}
